Looking at this logic puzzle, I need to systematically work through the constraints. Let me use Python to solve this by checking all possible permutations against the clues.

```python
from itertools import permutations

def solve_puzzle():
    people = ['Blake', 'Casey', 'Harper', 'Morgan', 'Sawyer']
    colors = ['blue', 'green', 'orange', 'red', 'yellow']
    pets = ['bird', 'dog', 'fish', 'horse', 'rabbit']
    drinks = ['cocoa', 'coffee', 'juice', 'milk', 'tea']
    hobbies = ['baking', 'fencing', 'hiking', 'painting', 'rowing']

    solutions = []

    for people_perm in permutations(people):
        for colors_perm in permutations(colors):
            for pets_perm in permutations(pets):
                for drinks_perm in permutations(drinks):
                    for hobbies_perm in permutations(hobbies):
                        houses = [
                            {
                                'person': people_perm[i],
                                'color': colors_perm[i],
                                'pet': pets_perm[i],
                                'drink': drinks_perm[i],
                                'hobby': hobbies_perm[i]
                            }
                            for i in range(5)
                        ]

                        if check_constraints(houses):
                            solutions.append(houses)

    return solutions

def check_constraints(houses):
    def find_pos(attr, value):
        for i in range(5):
            if houses[i][attr] == value:
                return i
        return -1

    def is_adjacent(pos1, pos2):
        return abs(pos1 - pos2) == 1

    # Clue 1: Orange house ≠ painting
    for h in houses:
        if h['color'] == 'orange' and h['hobby'] == 'painting':
            return False

    # Clue 2: Horse owner ≠ Blake
    for h in houses:
        if h['pet'] == 'horse' and h['person'] == 'Blake':
            return False

    # Clue 3: Blue house immediately left of Sawyer
    sawyer_pos = find_pos('person', 'Sawyer')
    if sawyer_pos == -1 or sawyer_pos == 0 or houses[sawyer_pos - 1]['color'] != 'blue':
        return False

    # Clue 4: Casey next to hiking person
    casey_pos = find_pos('person', 'Casey')
    hiking_pos = find_pos('hobby', 'hiking')
    if casey_pos == -1 or hiking_pos == -1 or not is_adjacent(casey_pos, hiking_pos):
        return False

    # Clue 5: Baking immediately left of tea
    baking_pos = find_pos('hobby', 'baking')
    tea_pos = find_pos('drink', 'tea')
    if baking_pos == -1 or tea_pos == -1 or baking_pos + 1 != tea_pos:
        return False

    # Clue 6: Baking immediately left of dog owner
    dog_pos = find_pos('pet', 'dog')
    if dog_pos == -1 or baking_pos + 1 != dog_pos:
        return False

    # Clue 7: Rabbit owner next to fencing person
    rabbit_pos = find_pos('pet', 'rabbit')
    fencing_pos = find_pos('hobby', 'fencing')
    if rabbit_pos == -1 or fencing_pos == -1 or not is_adjacent(rabbit_pos, fencing_pos):
        return False

    # Clue 8: Tea drinker next to horse owner
    horse_pos = find_pos('pet', 'horse')
    if horse_pos == -1 or not is_adjacent(tea_pos, horse_pos):
        return False

    # Clue 9: Casey next to bird owner
    bird_pos = find_pos('pet', 'bird')
    if bird_pos == -1 or not is_adjacent(casey_pos, bird_pos):
        return False

    # Clue 10: Red house next to rabbit owner
    red_pos = find_pos('color', 'red')
    if red_pos == -1 or not is_adjacent(red_pos, rabbit_pos):
        return False

    # Clue 11: Cocoa drinker next to orange house
    cocoa_pos = find_pos('drink', 'cocoa')
    orange_pos = find_pos('color', 'orange')
    if cocoa_pos == -1 or orange_pos == -1 or not is_adjacent(cocoa_pos, orange_pos):
        return False

    # Clue 12: Yellow house = rowing
    yellow_pos = find_pos('color', 'yellow')
    rowing_pos = find_pos('hobby', 'rowing')
    if yellow_pos != rowing_pos:
        return False

    # Clue 13: Bird owner is Harper
    if bird_pos == -1 or houses[bird_pos]['person'] != 'Harper':
        return False

    # Clue 14: Sawyer drinks juice
    juice_pos = find_pos('drink', 'juice')
    if juice_pos != sawyer_pos:
        return False

    # Clue 15: Blue house immediately left of painting
    blue_pos = find_pos('color', 'blue')
    painting_pos = find_pos('hobby', 'painting')
    if blue_pos == -1 or blue_pos + 1 != painting_pos:
        return False

    # Clue 16: Bird owner drinks milk
    milk_pos = find_pos('drink', 'milk')
    if milk_pos != bird_pos:
        return False

    return True

solutions = solve_puzzle()
print(f"Found {len(solutions)} solution(s)")
if len(solutions) > 0:
    for idx, sol in enumerate(solutions):
        print(f"\nSolution {idx + 1}:")
        for i, h in enumerate(sol):
            print(f"House {i+1}: {h['person']:8} | {h['color']:8} | {h['pet']:8} | {h['drink']:8} | {h['hobby']:8}")

        # Find and print bird owner
        for h in sol:
            if h['pet'] == 'bird':
                bird_owner = h['person']
                print(f"\nBird owner: {bird_owner}")
```

